        return 1;
    }

    const char *target_file = argv[1];
    const char *data = argv[2];
    size_t data_len = strlen(data);

    // Create a pipe
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        return 1;
    }

    // Open the target file
    int fd = open(target_file, O_RDONLY);
    if (fd == -1) {
        perror("open");
        close(pipefd[0]);
        close(pipefd[1]);
        return 1;
    }

    // Write data to the pipe
    ssize_t written = write(pipefd[1], data, data_len);
    if (written == -1) {
        perror("write");
        close(pipefd[0]);
        close(pipefd[1]);
        close(fd);
        return 1;
    }

    // Use splice to move data from pipe to file
    ssize_t spliced = splice(pipefd[0], NULL, fd, NULL, data_len, 0);
    if (spliced == -1) {
        perror("splice");
        close(pipefd[0]);
        close(pipefd[1]);
        close(fd);
        return 1;
    }

    // Verify the write
